-- 015_import_marg_hsn_master.sql
-- Imports 197 HSN/SAC master codes from Borgang Drug Distributors Marg ERP export (HSN MASTER.XLS)

DO $$
DECLARE
  org_rec RECORD;
BEGIN
  FOR org_rec IN SELECT id FROM public.organizations LOOP
    -- Clean up any invalid page artifact codes
    DELETE FROM public.hsn_codes WHERE organization_id = org_rec.id AND (code LIKE 'No..%' OR code LIKE 'Page%');

  END LOOP;
END $$;
